using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;
using sv_464de71a58e34483bc966102025463a9.Client;

namespace sv_464de71a58e34483bc966102025463a9.Auth;

/// <summary>
/// Server-side AuthenticationStateProvider that:
///   1. Returns a hardcoded identity for "bob@example.com" (roles: User, Editor).
///   2. Persists the identity into PersistentComponentState so the WebAssembly
///      runtime can restore it after the interactive handoff.
/// </summary>
public sealed class PersistingAuthenticationStateProvider : AuthenticationStateProvider, IDisposable
{
    private readonly PersistentComponentState _persistentState;
    private readonly PersistingComponentStateSubscription _subscription;
    private Task<AuthenticationState>? _authStateTask;

    public PersistingAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        _persistentState = persistentState;
        _subscription = persistentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        _authStateTask ??= BuildAuthenticationStateAsync();
        return _authStateTask;
    }

    private static Task<AuthenticationState> BuildAuthenticationStateAsync()
    {
        var claims = new[]
        {
            new Claim(ClaimTypes.Name, "bob@example.com"),
            new Claim(ClaimTypes.Email, "bob@example.com"),
            new Claim(ClaimTypes.Role, "User"),
            new Claim(ClaimTypes.Role, "Editor"),
        };

        var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
        var principal = new ClaimsPrincipal(identity);
        return Task.FromResult(new AuthenticationState(principal));
    }

    private async Task OnPersistingAsync()
    {
        var authState = await GetAuthenticationStateAsync();
        var user = authState.User;

        if (user.Identity?.IsAuthenticated != true)
            return;

        var userInfo = new UserInfo
        {
            Email = user.FindFirst(ClaimTypes.Email)!.Value,
            Roles = user.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray(),
        };

        _persistentState.PersistAsJson(nameof(UserInfo), userInfo);
    }

    public void Dispose() => _subscription.Dispose();
}

